import math

def check_nb(n):
    s_b_sum = 0
    for k in range(1, n + 1):
        harmonic_partial_sum = 0
        for i in range(k, n + 1):
            harmonic_partial_sum += 1.0 / i

        if harmonic_partial_sum == 0:
            return None # Should not happen for positive n

        s_b_sum += 1.0 / harmonic_partial_sum

    # If we set c = 1/n, we need n * s_b_sum to be an integer
    result = n * s_b_sum

    # Check if it's close to an integer due to floating point errors
    if abs(result - round(result)) < 1e-9:
        return round(result)
    else:
        return None

# Check n=1, 2, 3, 4
for n in range(1, 5):
    print(f"n={n}: {check_nb(n)}")
